1	#!/usr/bin/env node
2	/**
3	 * memory-protect-guard.mjs — PreToolUse hook (Write | Edit)
4	 *
5	 * Protege a "segunda memória" do Rafael contra a própria IA (LEI 10: trava, não promessa):
6	 *   1. REGRAS-DO-RAFAEL.md → IA NUNCA escreve/edita (só o Rafael, na mão).
7	 *   2. MEMORY.md → qualquer Write precisa PRESERVAR o bloco sentinela 🔒 do topo;
8	 *      qualquer Edit cujo old_string toque o bloco é bloqueado.
9	 * Sobrevive a compactação/renovação de memória porque roda no harness, fora da IA.
10	 */
11	import { readFileSync } from 'node:fs';
12	
13	let input = '';
14	try { input = readFileSync(0, 'utf8'); } catch { process.exit(0); }
15	let tool = {};
16	try { tool = JSON.parse(input); } catch { process.exit(0); }
17	const ti = tool?.tool_input || {};
18	const fp = String(ti.file_path || '').replace(/\\/g, '/').toLowerCase();
19	if (!fp) process.exit(0);
20	
21	const block = (msg) => { console.error(`[memory-protect-guard] BLOQUEADO: ${msg}`); process.exit(2); };
22	
23	// 1. Arquivo de regras: intocável pela IA, em qualquer projeto/path.
24	if (fp.endsWith('/regras-do-rafael.md')) {
25	  block('REGRAS-DO-RAFAEL.md é editado SÓ pelo Rafael na mão. Se ele quiser uma regra nova, redija a proposta na CONVERSA e peça pra ele colar.');
26	}
27	
28	// 2. MEMORY.md: o bloco sentinela do topo não pode sumir nem ser tocado.
29	if (fp.endsWith('/memory/memory.md')) {
30	  const SENT_INI = 'BLOCO INTOCÁVEL DO RAFAEL — INÍCIO';
31	  const SENT_FIM = 'BLOCO INTOCÁVEL DO RAFAEL — FIM';
32	  if (tool.tool_name === 'Write' || ti.content !== undefined) {
33	    const c = String(ti.content || '');
34	    if (!c.includes(SENT_INI) || !c.includes(SENT_FIM) || !c.includes('REGRAS-DO-RAFAEL.md')) {
35	      block('Write em MEMORY.md sem o bloco 🔒 do Rafael intacto no topo. Reescreva PRESERVANDO o bloco sentinela inteiro (INÍCIO/FIM + link REGRAS-DO-RAFAEL.md).');
36	    }
37	  }
38	  const oldS = String(ti.old_string || '');
39	  if (oldS && (oldS.includes(SENT_INI) || oldS.includes(SENT_FIM) || oldS.includes('LEIA PRIMEIRO, SEMPRE'))) {
40	    block('Edit tocando o bloco 🔒 do Rafael em MEMORY.md. Esse bloco não se edita, não se move e não se resume.');
41	  }
42	}
43	
44	process.exit(0);
45

1	#!/usr/bin/env node
2	// Hook PreToolUse (Bash|PowerShell) — GATE DESTRUTIVO.
3	//
4	// Barra a PRIMEIRA execução de comando destrutivo, exige justificativa em uma linha (o que
5	// afeta, como reverter, instrução do Rafael verbatim). A segunda tentativa do MESMO comando
6	// (mesma sha) passa — o modelo tem que dizer o texto pra ganhar o botão.
7	//
8	// Filosofia herdada do gateguard-fact-force (ecc, MIT), adaptada ao nosso tamanho:
9	// "self-evaluation não funciona (a resposta é sempre 'sim'); investigação sim". Aqui, o
10	// gate reduz o dano do 'apagar por preguiça' e do 'contorno silencioso' que já custaram
11	// caro (v. memory/conserto-nao-replicado-na-copia, memory/meia-vida-do-erro-proprio).
12	//
13	// Escopo: só ATOS destrutivos do shell — rm -rf, git push --force/:branch/--delete,
14	// git reset --hard, git clean -f, git branch -D (ou --delete --force), git checkout -- / . / HEAD <path>,
15	// git restore <path>, git worktree remove -f, git filter-branch, SQL destrutivo (DROP TABLE/DATABASE/
16	// SCHEMA/ROLE/USER, DELETE FROM, TRUNCATE) em contexto de execução SQL (psql/mysql/sqlite3/pg/mariadb -c),
17	// dd if=, Remove-Item -Recurse -Force, > arquivo (truncate standalone). Bash/PowerShell rotineiro passa direto.
18	//
19	// DECIDIDO NÃO cobrir (documentado em REN-172): `gh api -X DELETE` (workaround oficial do fechar-frente
20	// e genérico demais — bate em labels/comentários/reviews), `kill -9` (rotineiro em dev), `docker rmi -f`
21	// (não usamos Docker no fluxo diário). Se um dia precisar, aditamos.
22	//
23	// Kill switch: `ECC_DISABLE_BASH_DESTRUTIVO=1` (por sessão) ou renomeie/apague este arquivo.
24	//
25	// Estado: `~/.claude/hooks/.state/bash-destrutivo-<sessionId>.json` com array de shas já
26	// apresentadas. Grava ANTES de bloquear (segunda tentativa passa mesmo se disco falhar
27	// entre chamadas).
28	
29	import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
30	import { createHash } from 'node:crypto';
31	import { homedir } from 'node:os';
32	import { join } from 'node:path';
33	
34	const STATE_DIR = join(homedir(), '.claude', 'hooks', '.state');
35	
36	// --- detecção destrutiva ------------------------------------------------------
37	
38	// SQL destrutivo: DROP TABLE/DATABASE/SCHEMA/ROLE/USER/TABLESPACE, DELETE FROM, TRUNCATE, dd if=.
39	// Cuidado com FP: `drop_table_history()` (underscore, sem espaço) NÃO bate — a \s+ exige espaço.
40	const SQL_DD = /\b(drop\s+(?:table|database|schema|role|user|tablespace)\b|delete\s+from|truncate\s+table|truncate\s+\w|dd\s+if=)/i;
41	
42	// Clientes SQL onde -c/-e/--command carrega SQL executável — o valor entre aspas roda de verdade.
43	// Precisamos detectar SQL destrutivo AQUI ANTES de stripQuoted engolir o conteúdo das aspas.
44	const SQL_CLIENT_RX = /(?:^|[\s;|&`(])(psql|mysql|sqlite3|pg|mariadb)(?:\.exe)?\b/i;
45	const SQL_CMD_ARG_RX_QUOTED = /(?:-c|-e|--command|--execute)(?:\s+|=)(['"])([\s\S]*?)\1/g;
46	
47	// Extrai argumentos SQL crus (não-stripados) de comandos como `psql -c "DROP TABLE users"`.
48	// Só ativa se o segmento contiver um cliente SQL — evita processar comandos sem contexto.
49	function extractSqlExecutionArgs(seg) {
50	  if (!SQL_CLIENT_RX.test(seg)) return [];
51	  const args = [];
52	  let m;
53	  SQL_CMD_ARG_RX_QUOTED.lastIndex = 0;
54	  while ((m = SQL_CMD_ARG_RX_QUOTED.exec(seg)) !== null) {
55	    args.push(m[2]);
56	  }
57	  return args;
58	}
59	
60	// Remove conteúdo entre aspas simples/duplas — mensagem de commit com "drop table" NÃO dispara.
61	// Roda DEPOIS de extractSqlExecutionArgs, pra não perder SQL em contexto de execução.
62	function stripQuoted(cmd) {
63	  return String(cmd)
64	    .replace(/'(?:[^'\\]|\\.)*'/g, "''")
65	    .replace(/"(?:[^"\\]|\\.)*"/g, '""');
66	}
67	
68	function tokenize(seg) {
69	  return seg.split(/\s+/).filter(Boolean);
70	}
71	
72	function baseCmd(tok) {
73	  return String(tok || '')
74	    .replace(/^.*[\\/]/, '')
75	    .replace(/\.exe$/i, '')
76	    .toLowerCase();
77	}
78	
79	// rm -rf / -fr / -Rf / -r -f / --recursive --force
80	function isDestructiveRm(tokens) {
81	  if (baseCmd(tokens[0]) !== 'rm') return false;
82	  let hasR = false, hasF = false;
83	  for (const t of tokens.slice(1)) {
84	    if (t === '--recursive') { hasR = true; continue; }
85	    if (t === '--force') { hasF = true; continue; }
86	    if (!t.startsWith('-') || t.startsWith('--')) continue;
87	    const body = t.slice(1);
88	    if (/[rR]/.test(body)) hasR = true;
89	    if (/f/.test(body)) hasF = true;
90	  }
91	  return hasR && hasF;
92	}
93	
94	// git push --force (aceita --force-with-lease), git push :branch (delete via refspec),
95	// git push --delete <branch>.
96	function isDestructiveGitPush(tokens) {
97	  if (baseCmd(tokens[0]) !== 'git' || tokens[1] !== 'push') return false;
98	  const rest = tokens.slice(2);
99	  const hasForceWithLease = rest.some(t => t === '--force-with-lease' || t.startsWith('--force-with-lease='));
100	  if (!hasForceWithLease) {
101	    if (rest.some(t => t === '--force' || t === '-f' || /^-\w*f\w*$/.test(t))) return true;
102	  }
103	  // git push --delete <branch>
104	  if (rest.includes('--delete')) return true;
105	  // git push <remote> :<branch>  (delete via refspec — token começa com ':' e não é refs/tags/)
106	  if (rest.some(t => t.startsWith(':') && !t.startsWith(':refs/tags/'))) return true;
107	  return false;
108	}
109	
110	// git reset --hard, git clean -f, git branch -D (ou --delete --force),
111	// git checkout -- / . / HEAD <path>, git restore <path>,
112	// git worktree remove -f, git filter-branch.
113	function isDestructiveGitOther(tokens) {
114	  if (baseCmd(tokens[0]) !== 'git') return false;
115	  const sub = tokens[1];
116	  const rest = tokens.slice(2);
117	  if (sub === 'reset' && rest.includes('--hard')) return true;
118	  if (sub === 'clean' && rest.some(t => /^-\w*f/.test(t))) return true;
119	  if (sub === 'branch') {
120	    // Só destrutivo se force delete: -D, ou --delete --force juntos.
121	    // `--delete` sozinho é safe delete (recusa branch não-mergeada) → NÃO bloqueia (F13).
122	    if (rest.includes('-D')) return true;
123	    if (rest.includes('--delete') && rest.includes('--force')) return true;
124	  }
125	  if (sub === 'checkout') {
126	    // checkout -- <file> ou checkout .
127	    if (rest.includes('--')) return true;
128	    if (rest.includes('.')) return true;
129	    // checkout HEAD[~N|^] <path>  → descarta local pra revisão.
130	    // Rejeita: `checkout HEAD~1` sozinho (só troca ref), `checkout main` (troca branch).
131	    if (rest.length > 1 && /^HEAD([~^].*)?$/.test(rest[0]) && !rest[1].startsWith('-')) return true;
132	  }
133	  if (sub === 'restore' && !rest.includes('--staged')) {
134	    // git restore <path> descarta local — mesma classe de dano que checkout --
135	    if (rest.length > 0 && (rest.includes('.') || rest.some(t => !t.startsWith('-')))) return true;
136	  }
137	  if (sub === 'worktree' && rest[0] === 'remove') {
138	    if (rest.includes('--force') || rest.includes('-f')) return true;
139	  }
140	  if (sub === 'filter-branch') return true;
141	  return false;
142	}
143	
144	// Truncate por redirect standalone: `> arquivo` no início do segmento (sobrescreve/cria).
145	// Rotineiro `cmd > log.txt` (redirect com prefixo) passa — falso positivo seria absurdo aí.
146	// Rejeita `> /dev/null`, `> /dev/stdout`, `> /dev/stderr`.
147	function isDestructiveTruncate(seg) {
148	  const m = seg.match(/^\s*>\s*([^\s>&|;`]+)/);
149	  if (!m) return false;
150	  const target = m[1];
151	  return !/^\/dev\/(null|stdout|stderr)$/i.test(target);
152	}
153	
154	// PowerShell: Remove-Item -Recurse -Force
155	function isDestructivePwsh(seg) {
156	  return /\bRemove-Item\b.*(-Recurse|-r\b).*(-Force|-f\b)/i.test(seg)
157	      || /\bRemove-Item\b.*(-Force|-f\b).*(-Recurse|-r\b)/i.test(seg)
158	      || /\bClear-Content\b.*-Force/i.test(seg);
159	}
160	
161	function isDestructiveSegment(seg) {
162	  if (SQL_DD.test(seg)) return true;
163	  if (isDestructivePwsh(seg)) return true;
164	  if (isDestructiveTruncate(seg)) return true;
165	  const tokens = tokenize(seg);
166	  if (tokens.length === 0) return false;
167	  return isDestructiveRm(tokens) || isDestructiveGitPush(tokens) || isDestructiveGitOther(tokens);
168	}
169	
170	// Explode $(...) e `...` para segmentos de topo — pega `echo y | $(rm -rf /)`
171	// e crases equivalentes. Iterativo (até 4 níveis) pra tolerar aninhamento simples.
172	function explodeSubshells(cmd) {
173	  let out = cmd;
174	  for (let i = 0; i < 4; i += 1) {
175	    const before = out;
176	    out = out.replace(/\$\(([^()`]*)\)/g, ';$1;');
177	    out = out.replace(/`([^`]*)`/g, ';$1;');
178	    if (out === before) break;
179	  }
180	  return out;
181	}
182	
183	function detectDestructive(rawCmd) {
184	  // ORDEM importa:
185	  //   1) explodir subshells ANTES de tirar aspas (senão conteúdo do $() some com aspas externas)
186	  //   2) checar SQL em contexto de execução (psql -c "DROP TABLE") ANTES de strippar aspas
187	  //   3) só depois: stripQuoted + segmenta + detectores normais
188	  const exploded = explodeSubshells(String(rawCmd));
189	
190	  // (2) SQL em contexto de execução — args ainda com o conteúdo original das aspas
191	  const sqlArgs = extractSqlExecutionArgs(exploded);
192	  for (const arg of sqlArgs) {
193	    if (SQL_DD.test(arg)) return `${arg.slice(0, 80)}${arg.length > 80 ? '…' : ''} (em psql/mysql -c)`;
194	  }
195	
196	  // (3) fluxo normal
197	  const stripped = stripQuoted(exploded);
198	  const segments = stripped.split(/[;|&\n]+/).map(s => s.trim()).filter(Boolean);
199	  for (const seg of segments) {
200	    if (isDestructiveSegment(seg)) return seg;
201	  }
202	  return null;
203	}
204	
205	// --- estado -------------------------------------------------------------------
206	
207	function sha16(s) {
208	  return createHash('sha256').update(String(s)).digest('hex').slice(0, 16);
209	}
210	
211	function loadState(sessionId) {
212	  const p = join(STATE_DIR, `bash-destrutivo-${sessionId}.json`);
213	  try {
214	    if (existsSync(p)) return JSON.parse(readFileSync(p, 'utf8'));
215	  } catch {}
216	  return { shas: [] };
217	}
218	
219	function saveState(sessionId, state) {
220	  const p = join(STATE_DIR, `bash-destrutivo-${sessionId}.json`);
221	  try {
222	    if (!existsSync(STATE_DIR)) mkdirSync(STATE_DIR, { recursive: true });
223	    // cap: no máx 100 shas por sessão pra evitar crescer sem limite
224	    if (state.shas.length > 100) state.shas = state.shas.slice(-100);
225	    writeFileSync(p, JSON.stringify(state));
226	    return true;
227	  } catch {
228	    return false;
229	  }
230	}
231	
232	// --- entrada ------------------------------------------------------------------
233	
234	function readStdin() {
235	  return new Promise((resolve) => {
236	    let data = '';
237	    process.stdin.on('data', (c) => (data += c));
238	    process.stdin.on('end', () => resolve(data));
239	    setTimeout(() => resolve(data), 2000);
240	  });
241	}
242	
243	async function main() {
244	  try {
245	    if (String(process.env.ECC_DISABLE_BASH_DESTRUTIVO || '').match(/^(1|true|on|yes)$/i)) {
246	      return process.exit(0);
247	    }
248	    const raw = await readStdin();
249	    if (!raw) return process.exit(0);
250	    const input = JSON.parse(raw);
251	    const toolName = input.tool_name || '';
252	    if (toolName !== 'Bash' && toolName !== 'PowerShell') return process.exit(0);
253	    const cmd = (input.tool_input && input.tool_input.command) || '';
254	    if (!cmd) return process.exit(0);
255	
256	    const hit = detectDestructive(cmd);
257	    if (!hit) return process.exit(0);
258	
259	    const sessionId = input.session_id || 'unknown';
260	    const state = loadState(sessionId);
261	    const sha = sha16(cmd);
262	    if (state.shas.includes(sha)) return process.exit(0); // já apresentado, permite
263	
264	    // marca ANTES de bloquear — segunda tentativa passa mesmo se disco falhar depois
265	    state.shas.push(sha);
266	    saveState(sessionId, state);
267	
268	    process.stderr.write(
269	      '⛔ Gate destrutivo (1x por comando): antes de rodar este comando, apresente 3 linhas:\n' +
270	      '\n' +
271	      `   trecho: ${hit.slice(0, 120)}${hit.length > 120 ? '…' : ''}\n` +
272	      '\n' +
273	      '   1) O QUE afeta (arquivos, tabela, branch, refs concretas — não "o repo")\n' +
274	      '   2) COMO reverter em 1 linha (backup? git reflog? nada?)\n' +
275	      '   3) O QUE o Rafael pediu, verbatim (a frase dele, entre aspas)\n' +
276	      '\n' +
277	      'Depois de apresentar, execute o MESMO comando de novo — vai passar. Se não é isso que\n' +
278	      'você quer rodar, refaça o comando. Kill switch: ECC_DISABLE_BASH_DESTRUTIVO=1.'
279	    );
280	    return process.exit(2);
281	  } catch {
282	    // hook nunca deve matar tool call por bug próprio
283	    return process.exit(0);
284	  }
285	}
286	
287	main();
288

tools.description:
Open the Browser pane: pass `url` to open a browser tab at a URL (no dev server needed — use this for external sites, staging, docs, or your deployed app), OR pass `name` to start a dev server from .claude/launch.json.

Start a dev server by name from .claude/launch.json. If .claude/launch.json doesn't exist, create it first with this format:
{
  "version": "0.0.1",
  "configurations": [
    {
      "name": "<unique-name>",
      "runtimeExecutable": "<command>",
      "runtimeArgs": ["<args>"],
      "port": <port>
    }
  ]
}
Set "runtimeExecutable" to the command (e.g. "npm"), "runtimeArgs" to the arguments (e.g. ["run", "dev"]), and "port" to the server port. An optional "url" (http/https) opens the preview there instead of http://localhost:<port>. A localhost "url" must be just the server's origin — no path or query, matching the entry's port — for example "https://localhost:8443" or "http://app.localhost:3000"; to show a specific page, navigate after the preview opens. Non-localhost URLs may carry paths and are subject to the user's permission and the organization's browsing policy. A configuration with "url" and no command attaches to an already-running server. Only include servers you actually need to preview. Reuses the server if already running. ALWAYS use this instead of Bash for running servers. If the deliverable is already published as an Artifact, update the Artifact instead of starting a server to show it.

