1	#!/usr/bin/env node
2	/**
3	 * deploy-target-guard.mjs — PreToolUse hook (Bash | PowerShell)
4	 *
5	 * LEI 10 do Rafael: repetição de erro → ferramenta, não instrução.
6	 * Com 3 ambientes (staging + prod-temporada + prod-achamos), NENHUM comando de
7	 * deploy/migração pode rodar sem alvo EXPLÍCITO. Este hook intercepta o comando
8	 * ANTES de executar e bloqueia se o alvo estiver ausente ou desconhecido —
9	 * funciona mesmo com a memória da IA zerada/compactada.
10	 *
11	 * Alvos canônicos (ADR-079, tabela do CLAUDE.md):
12	 *   staging            → rzbfrmvyxcxxtpdraudz
13	 *   production-temporada → odcgnzfremrqnvtitpcc
14	 *   production-achamos   → txtjgczluzxvolswfsaw
15	 */
16	import { readFileSync } from 'node:fs';
17	
18	const ENVS = {
19	  rzbfrmvyxcxxtpdraudz: 'STAGING',
20	  odcgnzfremrqnvtitpcc: 'PRODUCAO TEMPORADA',
21	  txtjgczluzxvolswfsaw: 'PRODUCAO ACHAMOS',
22	};
23	
24	let input = '';
25	try { input = readFileSync(0, 'utf8'); } catch { process.exit(0); }
26	let cmd = '';
27	try { cmd = JSON.parse(input)?.tool_input?.command || ''; } catch { process.exit(0); }
28	if (!cmd) process.exit(0);
29	
30	const block = (msg) => {
31	  console.error(
32	    `[deploy-target-guard] BLOQUEADO: ${msg}\n` +
33	    `Alvos validos (declare EXPLICITAMENTE, ADR-079):\n` +
34	    `  - STAGING:             --project-ref rzbfrmvyxcxxtpdraudz  (ou -Target staging)\n` +
35	    `  - PRODUCAO TEMPORADA:  --project-ref odcgnzfremrqnvtitpcc  (ou -Target production / npm run promote:all)\n` +
36	    `  - PRODUCAO ACHAMOS:    --project-ref txtjgczluzxvolswfsaw  (fase DEFERIDA — exige ordem especifica do Rafael)\n` +
37	    `Regra: todo deploy/migracao declara o ambiente no proprio comando. Na duvida, PERGUNTE ao Rafael qual e o alvo.`,
38	  );
39	  process.exit(2); // exit 2 = bloqueia a ferramenta e devolve o stderr pra IA
40	};
41	
42	const note = (msg) => { console.log(`[deploy-target-guard] ${msg}`); process.exit(0); };
43	
44	const findRef = () => Object.keys(ENVS).find((r) => cmd.includes(r));
45	
46	// ── Edge Functions (supabase functions deploy) ──────────────────────────────
47	if (/supabase\s+(functions\s+deploy|db\s+push|migration\s+up|db\s+reset)/i.test(cmd)) {
48	  const ref = findRef();
49	  if (!ref) block('comando Supabase de deploy/migracao SEM --project-ref explicito.');
50	  if (/db\s+reset/i.test(cmd) && ENVS[ref] !== 'STAGING') block(`db reset em ${ENVS[ref]} — jamais.`);
51	  note(`ALVO CONFIRMADO: ${ENVS[ref]} (${ref}). Se nao era essa a intencao, aborte.`);
52	}
53	
54	// ── Migrations via scripts do repo ──────────────────────────────────────────
55	if (/apply-migrations-environment\.ps1|migrations:safe:apply/i.test(cmd)) {
56	  if (!/-Target\s+(staging|production)|safe:apply:(staging|production)/i.test(cmd)) {
57	    block('apply de migrations sem -Target explicito (staging|production).');
58	  }
59	  const prod = /-Target\s+production|apply:production/i.test(cmd);
