351	// ─── I/O: monta cfg/raizes do mundo real e chama a porta ───────────────────────────────────────────
352	function git(args, cwd, timeout = 5000) {
353	  try { return execFileSync('git', args, { cwd, encoding: 'utf-8', stdio: ['ignore', 'pipe', 'ignore'], timeout }).trim(); }
