357	// Raízes fixas do MUNDO REAL deste guard — nunca hardcoded como string: derivadas do próprio
358	// `import.meta.url` (TG-03) e do homedir (TG-02). `KIT_ROOT` é uma pasta acima de `hooks/`.
359	const KIT_ROOT = dirname(dirname(fileURLToPath(import.meta.url)));
360	const KIT_ROOT_REAL = resolverCaminhoReal(KIT_ROOT, KIT_ROOT);
361	const HOME_REAL = resolverCaminhoReal(homedir(), homedir());
362	const PASTA_MAE_REAL = resolverCaminhoReal(dirname(KIT_ROOT), dirname(KIT_ROOT)); // pai do kit ("C:/OUTROS PROJETOS - CLAUDE"), nunca hardcoded
363	
364	// TG-01(a)/RONDA 2: `commonDirSemSpawn`/`lerShaBranchSemSpawn`/`hashCommonDir`/`lerCache`/`escreverCache`
365	// vêm de `./lib/territorio-cache.mjs` (dono único do "ler git sem spawn" e do cache em disco).
366	const VERSAO_CACHE = 1;
367	
368	/** TG-01(a): O único spawn permitido pra config, mesmo em leitura/Bash (TG-12) — só no CACHE FRIO ou
369	 *  quando o sha mudou (`lerConfigCommitada`); no cache quente, zero spawn. */
370	function gitShowTexto(commonDir, cwd, ref, caminhoNoRepo) {
371	  try {
372	    const out = execFileSync('git', ['--git-dir', commonDir, 'show', `${ref}:${caminhoNoRepo}`], {
373	      cwd, encoding: 'utf-8', stdio: ['ignore', 'pipe', 'ignore'], timeout: 5000,
374	    });
375	    return { ok: true, texto: out };
376	  } catch { return { ok: false, texto: '' }; }
377	}
378	
379	/** O resultado (não o cache em si) de ler `branchBase:esteira.json` — 'bootstrap' (branch ainda sem o
380	 *  arquivo), 'invalido' (JSON quebrado ou reprovado por validarTerritorio) ou 'valido' (território). */
381	function computarResultadoCommitado(commonDir, root, branchBase) {
382	  const show = gitShowTexto(commonDir, root, branchBase, 'esteira.json');
383	  if (!show.ok) return { tipo: 'bootstrap' };
384	  let parsed;
385	  try { parsed = JSON.parse(show.texto); }
386	  catch { return { tipo: 'invalido', motivo: 'esteira.json COMMITADO na branch base é JSON inválido' }; }
387	  try { return { tipo: 'valido', ...validarTerritorio(parsed, root) }; }
388	  catch (e) { return { tipo: 'invalido', motivo: `esteira.json COMMITADO na branch base é inválido: ${e.message}` }; }
389	}
390	
391	/**
392	 * TG-01(a) + RONDA 2: devolve o resultado da config commitada, SEM spawn quando o cache bate com o sha
393	 * atual (lido do disco via `lerShaBranchSemSpawn`). Sha novo (ou sem cache, ou cache corrompido/de outra
394	 * versão) → UM `git show` (via `computarResultadoCommitado`) e regrava o cache com o sha novo. `null` =
395	 * sha não deu pra resolver sem spawn (repo atípico, limite (f)) — sem cache, quem chama cai pro disco.
396	 */
397	function lerConfigCommitada(commonDir, root, branchBase) {
398	  const sha = lerShaBranchSemSpawn(commonDir, branchBase);
399	  if (!sha) return null;
400	  const chave = hashCommonDir(commonDir);
401	  const cache = lerCache(chave, VERSAO_CACHE);
402	  if (cache && cache.sha === sha) return cache.resultado; // CACHE QUENTE: zero spawn, zero node extra
403	  const resultado = computarResultadoCommitado(commonDir, root, branchBase); // CACHE FRIO ou sha mudou: 1 spawn
404	  escreverCache(chave, { sha, versaoDoHook: VERSAO_CACHE, resultado });
405	  return resultado;
406	}
407	
408	/**
409	 * TG-02: valida os campos de TERRITÓRIO (`projeto`/`wt_root`/`vault_dir`) de um esteira.json já
410	 * parseado — disco OU a versão COMMITADA (git show). DUPLICA uma fatia da validação de
411	 * `scripts/lib/esteira.mjs` (`getEsteira`) porque aqui a fonte pode ser TEXTO puro; unificar as duas é
412	 * decisão de OUTRA frente (ver "O QUE NÃO VÊ" (g)). Lança Error com a violação — quem chama decide o
413	 * fail-closed. `raiz` é usada só pra resolver `wt_root`/`vault_dir` relativos (defensivo; a convenção é
414	 * sempre absoluto).
415	 */
416	function validarTerritorio(cfg, raiz) {
417	  if (!cfg || typeof cfg !== 'object' || Array.isArray(cfg)) throw new Error('esteira.json não é um objeto');
418	  if (!cfg.projeto || !/^[a-z0-9][a-z0-9._-]*$/.test(String(cfg.projeto))) throw new Error("'projeto' inválido");
419	  if (!cfg.wt_root) throw new Error("falta 'wt_root'");
420	
421	  const validaRaiz = (bruto, nomeCampo) => {
422	    const n = normalizarTexto(resolveAbs(raiz, String(bruto))).replace(/\/+$/, '');
423	    const segs = n.split('/');
424	    if (segs.length < 3) throw new Error(`'${nomeCampo}' precisa de ≥2 segmentos abaixo do drive: ${bruto}`);
425	    if (segs[segs.length - 1] !== normalizarTexto(cfg.projeto)) throw new Error(`'${nomeCampo}' não termina em /${cfg.projeto}: ${bruto}`);
426	    return n;
427	  };
428	  const wtRoot = validaRaiz(cfg.wt_root, 'wt_root');
429	  const vaultDir = cfg.vault_dir ? validaRaiz(cfg.vault_dir, 'vault_dir') : '';
430	
431	  // TG-02: nem wt_root nem vault_dir podem ser ANCESTRAIS do kit, do home, ou da pasta-mãe dos projetos
432	  // — "C:/" (ou qualquer raiz larga demais) vira config INVÁLIDA em vez de liberar o disco.
433	  for (const raizCandidata of [wtRoot, vaultDir].filter(Boolean)) {
434	    for (const areaAlheia of [KIT_ROOT_REAL, HOME_REAL, PASTA_MAE_REAL]) {
435	      if (areaAlheia && dentroDe(areaAlheia, raizCandidata)) {
436	        throw new Error(`território largo demais: '${raizCandidata}' é ancestral de área alheia`);
437	      }
438	    }
439	  }
440	
441	  const pastasProibidas = Array.isArray(cfg.pastas_proibidas)
442	    ? cfg.pastas_proibidas.filter((p) => typeof p === 'string' && p) : [];
443	  return { projeto: cfg.projeto, wtRoot, vaultDir, pastasProibidas, branchBase: cfg.branch_base ? String(cfg.branch_base) : undefined };
444	}
