446	function pastasProibidasCruDoDisco(configPath) {
447	  try {
448	    const bruto = JSON.parse(readFileSync(configPath, 'utf8'));
449	    if (Array.isArray(bruto.pastas_proibidas)) return bruto.pastas_proibidas.filter((p) => typeof p === 'string' && p);
450	  } catch { /* ignora-de-proposito: JSON quebrado — pastas_proibidas cru fica vazio (TG-04 ainda roda com []) */ }
451	  return [];
452	}
