456	  try { root = findEsteiraRoot(cwd); } catch { root = null; }
457	  if (!root) return null; // sem esteira.json: fora da família -base, silêncio
458	  if (/[OUTRO-PROJETO]/i.test(root)) return null; // território do [OUTRO-PROJETO]: a família -base não atua ali
459	
460	  // TG-03: isenção do kit só por REALPATH da raiz da sessão == REALPATH da raiz do kit — nunca por
461	  // `projeto === "projeto-base"` (um projeto qualquer podia se autonomear assim e ganhar a isenção).
462	  const rootReal = resolverCaminhoReal(root, root);
463	  if (rootReal === KIT_ROOT_REAL) return { isKit: true };
464	
465	  let cfgDisco;
466	  try { cfgDisco = getEsteira(cwd); }
467	  catch { return { invalido: true, configPath: `${root}/esteira.json`, repoRoot: root, pastasProibidas: pastasProibidasCruDoDisco(`${root}/esteira.json`) }; }
468	
469	  const pastasProibidasDisco = pastasProibidasCruDoDisco(cfgDisco.configPath);
470	
471	  // TG-01(a): a config de TERRITÓRIO de verdade é a COMMITADA em branch_base do repo PRINCIPAL — uma
472	  // frente não muda a branch base sem merge do dono. Só cai pro disco se a branch base ainda não tiver
473	  // esteira.json (projeto recém-bootstrapado), o sha não resolver sem spawn, ou o common-dir/git falhar
474	  // (limite (f)). RONDA 2: `lerConfigCommitada` só spawna git no cache frio ou quando o sha mudou.
475	  let projeto = cfgDisco.projeto, wtRoot = cfgDisco.wtRoot, vaultDir = cfgDisco.vaultDir, pastasProibidas = pastasProibidasDisco;
476	  const commonDir = commonDirSemSpawn(root);
477	  const repoRootPrincipal = commonDir ? dirname(commonDir).replaceAll('\\', '/').replace(/\/+$/, '') : '';
478	
479	  if (commonDir && cfgDisco.branchBase) {
480	    const resultado = lerConfigCommitada(commonDir, root, cfgDisco.branchBase);
481	    if (resultado && resultado.tipo === 'invalido') {
482	      return { invalido: true, configPath: cfgDisco.configPath, repoRoot: root, pastasProibidas: pastasProibidasDisco, motivoInvalido: resultado.motivo };
483	    }
484	    if (resultado && resultado.tipo === 'valido') {
485	      projeto = resultado.projeto; wtRoot = resultado.wtRoot; vaultDir = resultado.vaultDir || vaultDir; pastasProibidas = resultado.pastasProibidas;
486	    }
487	    // resultado === null (sha não resolveu sem spawn) ou tipo 'bootstrap': segue com os valores do disco.
488	  }
489	
