491	  try { validarTerritorio({ projeto, wt_root: wtRoot, vault_dir: vaultDir, pastas_proibidas: pastasProibidas }, root); }
492	  catch (e) {
493	    return { invalido: true, configPath: cfgDisco.configPath, repoRoot: root, pastasProibidas: pastasProibidasDisco, motivoInvalido: e.message };
494	  }
495	
496	  return { ...cfgDisco, projeto, wtRoot, vaultDir, pastasProibidas, repoRoot: root, repoRootPrincipal, isKit: false };
497	}
