499	/** TG-07: slugs EXATOS liberados pra memória de escrita — raiz principal + cada worktree real. Só
500	 *  chamado pra ferramentas de ESCRITA (TG-12: `git worktree list` nunca roda em leitura/Bash). */
501	function slugsDeFrentesValidas(cwd, repoRootPrincipal) {
502	  const slugs = new Set();
503	  const paraSlug = (p) => normalizarTexto(slugDeProjeto(String(p).replaceAll('/', '\\')));
504	  if (repoRootPrincipal) slugs.add(paraSlug(repoRootPrincipal));
505	  const saida = git(['worktree', 'list', '--porcelain'], cwd);
506	  for (const linha of saida.split('\n')) {
507	    const m = linha.match(/^worktree\s+(.+)$/);
508	    if (m) slugs.add(paraSlug(m[1].trim()));
509	  }
510	  return slugs;
511	}
