513	function dedupe(arr) { return [...new Set((arr || []).filter(Boolean))]; }
514	
515	function construirRaizes(cfg, cwd, toolName) {
516	  if (cfg.isKit) return { resolver: resolverCaminhoReal, escrita: [], leituraProibida: [], pastasProibidasBrutas: [], memoria: {} };
517	
518	  const ehEscrita = FERRAMENTAS_ESCRITA.has(toolName);
519	  const escrita = [];
