521	  // diferente na declaração da raiz não escapa mais da comparação.
522	  const add = (p) => { if (p) escrita.push(resolverCaminhoReal(p, p)); };
523	
524	  if (cfg.invalido) {
525	    add(cfg.repoRoot);
526	    return {
527	      resolver: resolverCaminhoReal,
528	      escrita: dedupe(escrita),
529	      leituraProibida: (cfg.pastasProibidas || []).map((p) => resolverCaminhoReal(p, cwd)),
530	      pastasProibidasBrutas: (cfg.pastasProibidas || []).map((p) => normalizarTexto(p).replace(/\/+$/, '')),
531	      memoria: {},
532	    };
533	  }
534	
535	  // Território por PAPEL do cwd (decisão do coordenador; dono único da pergunta é `papelDoCwd`,
536	  // hooks/lib/base-hook-lib.mjs): a própria árvore encontrada — NUNCA `wt_root` inteiro. Isso já
537	  // resolve "frente" (só a própria worktree), "integração" (só a árvore principal) e "auditoria" (só o
538	  // clone) da mesma forma, porque `cfg.repoRoot` É a árvore que o cwd está — não precisa reconstruir.
539	  // "replica" não foi nomeado na decisão do coordenador — tratado como "frente" (mesma restrição,
540	  // leitura conservadora — ver "O QUE NÃO VÊ" (h)).
541	  add(cfg.repoRoot);
542	  if (ehEscrita) add(git(['rev-parse', '--show-toplevel'], cwd)); // TG-12: só pra escrita
543	
544	  if (cfg.repoRootPrincipal) add(cfg.repoRootPrincipal);
545	  add(cfg.vaultDir);
546	  add(join(homedir(), '.claude', 'plans'));
547	  add(tmpdir());
548	  add(memoryDirDe(cfg.repoRootPrincipal || cfg.repoRoot));
549	
550	  let slugsValidos = new Set();
551	  if (ehEscrita) slugsValidos = slugsDeFrentesValidas(cwd, cfg.repoRootPrincipal || cfg.repoRoot); // TG-12 + TG-07
552	
553	  return {
554	    resolver: resolverCaminhoReal,
555	    escrita: dedupe(escrita),
556	    leituraProibida: (cfg.pastasProibidas || []).map((p) => resolverCaminhoReal(p, cwd)),
