#!/usr/bin/env node
/**
 * namastex-widget-guard.mjs — PreToolUse hook (AskUserQuestion)
 *
 * LEI 8 do projeto namastex-fde-challenge (docs/LEIS-DO-PROJETO.md): pergunta de ticar
 * (widget AskUserQuestion) é proibida — pare quando a decisão não é sua, e widget custa o
 * trabalho DO DONO de ir destravar a sessão. Um chat de frente usou a ferramenta mesmo assim;
 * o dono (Rafael) autorizou esta trava em 2026-09-13.
 *
 * Só age DENTRO da árvore do projeto — raiz em
 * `C:\OUTROS PROJETOS - CLAUDE\namastex-fde-challenge` e worktrees em
 * `C:/base-wt/namastex-fde-challenge/<slug>` (substring "namastex-fde-challenge" no cwd,
 * normalizado e sem diferenciar maiúsculas). Fora disso: silêncio total (exit 0) — nunca toca
 * outro projeto, [OUTRO-PROJETO] incluso.
 */
import { readFileSync } from 'node:fs';

let input = '';
try { input = readFileSync(0, 'utf8'); } catch { process.exit(0); }
let tool = {};
try { tool = JSON.parse(input); } catch { process.exit(0); }

const cwd = String(tool?.cwd || process.cwd()).replace(/\\/g, '/').toLowerCase();
if (!cwd.includes('namastex-fde-challenge')) process.exit(0);

if (tool.tool_name === 'AskUserQuestion') {
  console.error(
    '[namastex-widget-guard] BLOQUEADO — LEI 8 do projeto (docs/LEIS-DO-PROJETO.md): pergunta de ticar ' +
    'é proibida, para o dono e para a coordenação. Widget deixa a sessão surda e obriga o dono a ir ' +
    'destravar. Escreva a pergunta em TEXTO SIMPLES: (1) a pergunta, (2) as alternativas que você ' +
    'enxerga, (3) qual você recomenda e por quê. Publique também como comentário na issue da frente e ' +
    'siga com o que não depende da resposta.'
  );
  process.exit(2);
}

process.exit(0);

